namespace Astronomy.MediaFactory.Core.KnowledgeFoundation.Catalog;
public sealed class AstronomyKnowledgeCatalogSnapshot
{
    public AstronomyKnowledgeCatalogSnapshot(IEnumerable<AstronomyKnowledgeCatalogEntry> entries){ ArgumentNullException.ThrowIfNull(entries); var a=entries.Select(e=>e??throw new ArgumentException("Catalog entries cannot contain null.",nameof(entries))).ToArray(); var dup=a.GroupBy(e=>e.Id).FirstOrDefault(g=>g.Count()>1); if(dup!=null) throw new ArgumentException($"Duplicate catalog entry ID '{dup.Key}'.",nameof(entries)); var code=a.GroupBy(e=>(e.Kind,e.Code), new KeyComparer()).FirstOrDefault(g=>g.Count()>1); if(code!=null) throw new ArgumentException($"Duplicate catalog code '{code.Key.Code}'.",nameof(entries)); Entries=Array.AsReadOnly(a.OrderBy(e=>e.Kind).ThenBy(e=>e.Order).ThenBy(e=>e.Code,StringComparer.Ordinal).ThenBy(e=>e.Id.Value,StringComparer.Ordinal).ToArray()); Domains=Kind(AstronomyKnowledgeCatalogEntryKind.Domain); PayloadFamilies=Kind(AstronomyKnowledgeCatalogEntryKind.PayloadFamily); KnowledgeTypes=Kind(AstronomyKnowledgeCatalogEntryKind.KnowledgeType); ValidationRules=Kind(AstronomyKnowledgeCatalogEntryKind.ValidationRule); CrossDomainValidationRules=Kind(AstronomyKnowledgeCatalogEntryKind.CrossDomainValidationRule); GraphValidationRules=Kind(AstronomyKnowledgeCatalogEntryKind.GraphValidationRule); StatementKinds=Kind(AstronomyKnowledgeCatalogEntryKind.StatementKind); }
    IReadOnlyList<AstronomyKnowledgeCatalogEntry> Kind(AstronomyKnowledgeCatalogEntryKind k)=>Array.AsReadOnly(Entries.Where(e=>e.Kind==k).ToArray());
    public IReadOnlyList<AstronomyKnowledgeCatalogEntry> Entries{get;} public IReadOnlyList<AstronomyKnowledgeCatalogEntry> Domains{get;} public IReadOnlyList<AstronomyKnowledgeCatalogEntry> PayloadFamilies{get;} public IReadOnlyList<AstronomyKnowledgeCatalogEntry> KnowledgeTypes{get;} public IReadOnlyList<AstronomyKnowledgeCatalogEntry> ValidationRules{get;} public IReadOnlyList<AstronomyKnowledgeCatalogEntry> CrossDomainValidationRules{get;} public IReadOnlyList<AstronomyKnowledgeCatalogEntry> GraphValidationRules{get;} public IReadOnlyList<AstronomyKnowledgeCatalogEntry> StatementKinds{get;}
    sealed class KeyComparer:IEqualityComparer<(AstronomyKnowledgeCatalogEntryKind Kind,string Code)>{ public bool Equals((AstronomyKnowledgeCatalogEntryKind Kind,string Code)x,(AstronomyKnowledgeCatalogEntryKind Kind,string Code)y)=>x.Kind==y.Kind&&StringComparer.Ordinal.Equals(x.Code,y.Code); public int GetHashCode((AstronomyKnowledgeCatalogEntryKind Kind,string Code)o)=>HashCode.Combine(o.Kind,StringComparer.Ordinal.GetHashCode(o.Code));}
}
